function renderDeliveries(items){const nodes=items.map(item=>{const row=element('tr'),chat=(snapshot.data.chats||[]).find(c=>String(c.bot_id)===String(item.bot_id)&&String(c.chat_id)===String(item.chat_id));cell(row,chat?.title||`Chat ${item.chat_id}`);const text=compactText(item.text);if(item.message_id)text.append(element('small',`Telegram message ${item.message_id}`));cell(row,text);const actions=element('div',undefined,'actions');actions.append(badge(deliveryState(item),!item.resolution&&item.state!=='sent'));const menu=deliveryMenu(item);if(menu)actions.append(menu);cell(row,actions);return keyed(row,`delivery/${item.job_id}/${item.part}`,{item,chat:chat?.title})});reconcile($('deliveries'),nodes,'No outgoing messages yet.',3)}

// Settings are grouped by key prefix into inset lists; Save appears once a value changes.
const settingGroups={agent_id:'General',log_level:'General',bots:'Bots',limits:'Limits',llm:'Language model',memory:'Memory',observability:'Observability',telegram:'Telegram',quotas:'Quotas'};
const groupOf=name=>settingGroups[name]||settingGroups[name.split('.')[0]]||'Other';
const settingLabel=name=>{const key=name.split('.').at(-1).replaceAll('_',' ');return key.charAt(0).toUpperCase()+key.slice(1)};
const settingHint=name=>name.includes('timeout')?'Maximum wait before the operation fails.':name.includes('bytes')?'Maximum allowed size in bytes.':name.includes('concurrency')?'Maximum number of simultaneous operations.':name.includes('model')?'Model identifier used by the configured provider.':name.includes('endpoint')?'Service endpoint URL.':name.includes('interval')||name.includes('window')||name.includes('poll')||name.includes('lease')?'Duration such as 30s, 5m or 1h.':name.includes('quota')||name.includes('calls_per')?'Usage limit; 0 disables the limit.':name.includes('rounds')||name.includes('messages')||name.includes('tokens')?'Maximum count for one operation.':'Advanced runtime value.';
async function loadSettings(){const rows=(await api('/api/settings?scope='+$('settings-scope').value)).filter(s=>s.name!=='mcp.servers').sort((a,b)=>a.name.localeCompare(b.name));const filter=$('settings-search').value.trim().toLowerCase();const groups=new Map();for(const s of rows){const searchable=`${s.name} ${settingLabel(s.name)} ${settingHint(s.name)}`.toLowerCase();if(filter&&!searchable.includes(filter))continue;const g=groupOf(s.name);if(!groups.has(g))groups.set(g,[]);groups.get(g).push(s)}const nodes=[];
for(const [group,items] of groups){const wrap=element('div',undefined,'settings-group');const title=element('div',undefined,'card-title');title.append(element('span',group),element('small',`${items.filter(s=>s.overridden).length} overridden`));const card=element('div',undefined,'card');for(const setting of items){const row=element('div',undefined,'setting');const name=element('div',settingLabel(setting.name),'name');name.append(element('small',settingHint(setting.name),'setting-help'),element('small',setting.name,'setting-key'));row.append(name);const value=element('div',setting.secret?'Protected value':`Current: ${setting.effective_value||'—'}`,'value');if(setting.overridden)value.append(badge('Override',false,'info'));row.append(value);const input=element('input');input.type=setting.secret?'password':'text';const initial=setting.secret?'':(setting.overridden?setting.override_value:setting.effective_value);input.value=initial;input.autocomplete='off';input.setAttribute('aria-label',setting.name);input.placeholder=setting.secret?'Enter replacement secret':'New value';row.append(input);const actions=element('div',undefined,'actions');const save=button('Save',async()=>{await api('/api/settings','POST',{scope:setting.scope,name:setting.name,value:input.value,version:setting.version});notice('Saved. Applying automatically…');await loadSettings()},'');save.hidden=true;input.oninput=()=>{const dirty=input.value!==initial;save.hidden=!dirty;row.classList.toggle('dirty',dirty)};input.onkeydown=e=>{if(e.key==='Enter'&&!save.hidden){e.preventDefault();save.click()}if(e.key==='Escape'){input.value=initial;input.oninput()}};actions.append(save);if(setting.overridden)actions.append(button('Reset',async()=>{if(!(await confirmAsync(`Reset ${settingLabel(setting.name)}?`,'The saved override is removed and the configured value applies.','Reset')))return;await api('/api/settings','DELETE',{scope:setting.scope,name:setting.name,version:setting.version});notice('Override removed. Applying configured value…');await loadSettings()}));row.append(actions);card.append(row)}wrap.append(title,card);nodes.push(keyed(wrap,'settings-group/'+group,items))}reconcile($('settings-list'),nodes,filter?'No settings match the search.':'No editable settings in this scope.')}
